	void link_tail_node(intrusive_node* node) {
		node->next = &root_;
		node->prev = root_.prev;
		root_.prev = root_.prev->next = node;
	}

	void unlink_node(intrusive_node* node) {
		node->next->prev = node->prev;
		node->prev->next = node->next;
	}

