	~dynamic_buffer() {
		clear();
	}

	dynamic_buffer& operator=(dynamic_buffer&& rhs) noexcept {
		move(rhs);
		return *this;
	}

	dynamic_buffer(dynamic_buffer&& rhs) noexcept {
		move(rhs);
	}

	dynamic_buffer(const dynamic_buffer& rhs) {
		copy(rhs);
	}

