  file_ = std::fopen(path, "a+b");

  if(!file_) {
   error_ = true;
   return;
  }

  if(std::fseek(file_, 0, SEEK_END)) {
   error_ = true;
   return;
  }

  write_ = std::ftell(file_);

  if(write_ == -1) {
   error_ = true;
  }
