file_buffer(const char* path) {
		file_ = std::fopen(path, "a+b");

		if(!file_) {
			error_ = true;
			return;
		}

		if(std::fseek(file_, 0, SEEK_END)) {
			error_ = true;
			return;
		}

		write_ = std::ftell(file_);

		if(write_ == -1) {
			error_ = true;
		}
	}

file_buffer(file_buffer&& rhs) noexcept
		: file_(rhs.file_),
		  read_(rhs.read_),
		  write_(rhs.write_),
		  error_(rhs.error_) {
		rhs.file_ = nullptr;
	}

~file_buffer() {
		close();
	}

