class block_allocator {
 using tid_type = std::conditional_t<
  std::is_same_v<ValidatePolicy, validate_dealloc>, std::thread::id, std::monostate
 >;

 struct mem_block {
  _ty obj;

  struct {
   [[no_unique_address]] tid_type thread_id;
   bool using_new;
  } meta;
